@CrossOrigin
@RestController
@RequestMapping("/RegulationQuery")
public class RegulationQueryRestController extends BaseSpringRestController {
	
	public RegulationQueryRestController( RegulationService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Regulation using a UUID
     * @param		UUID regulationId
     * @return		Regulation
     */    
    @GetMapping("/load")
    public Regulation load( @RequestParam(required=true) UUID regulationId ) {
    	Regulation entity = null;

    	try {  
    		entity = service.getRegulation( new RegulationFetchOneSummary( regulationId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Regulation using Id " + regulationId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Regulation business objects
     * @return		Set<Regulation>
     */
    @GetMapping("/")
    public List<Regulation> loadAll() {                
    	List<Regulation> regulationList = null;
        
    	try {
            // load the Regulation
            regulationList = service.getAllRegulation();
            
            if ( regulationList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Regulations" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Regulations ", exc );
        	return null;
        }

        return regulationList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Regulation regulation = null;
    protected RegulationService service = null;
    private static final Logger LOGGER = Logger.getLogger(RegulationQueryRestController.class.getName());
    
}
